static uint32_t djb2_hash(const char* str, size_t len)
{
    uint32_t h = 5381;
    size_t n = len < LLM_CACHE_KEY_LEN ? len : LLM_CACHE_KEY_LEN;

    for (size_t i = 0; i < n; i++) {
        h = ((h << 5) + h) + (unsigned char)str[i];
    }
    return h;
}

